    <title>V0 Particle Animation</title>
    <style>
        :root {
            primarybg: rgba(255, 255, 255, 0.1);
            bordercolor: rgba(255, 255, 255, 1);
            textcolor: white;
            hoverbg: rgba(255, 255, 255, 0.3);
        }

        body {
            margin: 0;
            padding: 0;
            overflow: hidden;
            backgroundcolor: 000;
            fontfamily: applesystem, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sansserif;
        }

        canvas {
            display: block;
        }

        .controlscontainer {
            position: absolute;
            top: 20px;
            left: 20px;
            display: flex;
            flexdirection: column;
            gap: 10px;
            background: rgba(0, 0, 0, 0.8);
            padding: 15px;
            borderradius: 8px;
            border: 1px solid var(bordercolor);
            backdropfilter: blur(5px);
            zindex: 10;
        }

        .controlscontainer label {
            color: var(textcolor);
            fontsize: 14px;
            marginbottom: 5px;
            display: block;
        }

        .controlscontainer select {
            background: var(primarybg);
            border: 1px solid var(bordercolor);
            color: var(textcolor);
            padding: 8px 12px;
            borderradius: 4px;
