            cursor: pointer;
            width: 200px;
            transition: background 0.2s;
        }

        .controlscontainer select:hover {
            background: var(hoverbg);
        }

        .effectscontainer {
            position: absolute;
            bottom: 20px;
            left: 20px;
            display: flex;
            flexdirection: column;
            gap: 8px;
            background: rgba(0, 0, 0, 0.8);
            padding: 15px;
            borderradius: 8px;
            border: 1px solid var(bordercolor);
            backdropfilter: blur(5px);
            zindex: 10;
        }

        .effectscontainer button {
            background: var(primarybg);
            border: 1px solid var(bordercolor);
            color: var(textcolor);
            padding: 8px 16px;
            borderradius: 4px;
            fontsize: 14px;
            cursor: pointer;
            transition: background 0.2s;
            textalign: left;
            width: 100%;
        }

        .effectscontainer button:hover {
            background: var(hoverbg);
        }

        .effectscontainer button.active {
            background: var(hoverbg);
            boxshadow: 0 0 10px rgba(255, 255, 255, 0.3);
        }

        .zoomcontainer {
            position: absolute;
            top: 20px;
            right: 20px;
            display: flex;
            flexdirection: column;
            gap: 8px;
