            const pax = px  ax;
            const pay = py  ay;
            const bax = cx  ax;
            const bay = cy  ay;
            const dotBaBa = bax  bax + bay  bay;
            const dotPaBa = pax  bax + pay  bay;
            const h = clamp(dotPaBa / dotBaBa, 0, 1);
            const dx = pax  bax  h;
            const dy = pay  bay  h;
            return Math.sqrt(dx  dx + dy  dy)  w;
