                if (implodeFactor > 0) {
                    const intensity = 1 + Math.sin(time  8  cdist  15)  0.5  implodeFactor;
                    r = intensity  2.0;
                    g = intensity  2.0;
                    b = intensity  10.0;
                }

                if (spiralFactor > 0) {
                    const angle = Math.atan2(cy, cx) + time  5;
                    const intensity = 10;
                    r = (Math.sin(angle)  0.5 + 0.5)  intensity;
                    g = (Math.sin(angle + (Math.PI  2) / 3)  0.5 + 0.5)  intensity;
