<body>
    <canvas id="particleCanvas"></canvas>

    <script>
        // Clamp utility
        const clamp = (value, min, max) => {
            return Math.max(min, Math.min(max, value));
        };

        // Initialize Three.js scene
        const canvas = document.getElementById('particleCanvas');
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, canvas.clientWidth / canvas.clientHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });

        // Set canvas size
        function resizeRenderer() {
            const width = window.innerWidth;
            const height = window.innerHeight;
            renderer.setSize(width, height);
            camera.aspect = width / height;
            camera.updateProjectionMatrix();
        }

        resizeRenderer();
        window.addEventListener('resize', resizeRenderer);

        const raycaster = new THREE.Raycaster();
        const mouse = new THREE.Vector2();
        const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);

        // Generate particles for 3D dandelion
        const numParticles = 50000;
        const positions = new Float32Array(numParticles * 3);
        const colors = new Float32Array(numParticles * 3);
        let particleCount = 0;

        // Head: uniform volume sampling in sphere
        const headRadius = 0.15;
        const numHeadParticles = 12000;
        for (let i = 0; i < numHeadParticles; i++) {
            const r = headRadius * Math.pow(Math.random(), 1 / 3);
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);
            const sinPhi = Math.sin(phi);
            const px = r * sinPhi * Math.cos(theta);
            const py = r * sinPhi * Math.sin(theta);
            const pz = r * Math.cos(phi);
            positions[particleCount * 3] = px;
            positions[particleCount * 3 + 1] = py;
            positions[particleCount * 3 + 2] = pz;
            colors[particleCount * 3] = 1;
            colors[particleCount * 3 + 1] = 1;
            colors[particleCount * 3 + 2] = 1;
            particleCount++;
        }

        // Directions for seeds: uniform upper hemisphere
        const numSeeds = 350;
        const directions = [];
        for (let i = 0; i < numSeeds; i++) {
            const height = Math.random();
            const azimuth = Math.random() * Math.PI * 2;
            const radial = Math.sqrt(1 - height * height);
            const dx = radial * Math.cos(azimuth);
            const dy = height;
            const dz = radial * Math.sin(azimuth);
            directions.push({ x: dx, y: dy, z: dz });
        }

        // Seeds: particles along each ray with thickness
        const particlesPerSeed = 100;
        const seedLength = 0.45;
        const startDist = headRadius * 1.02;
        const seedRadius = 0.012;
        for (let s = 0; s < numSeeds; s++) {
            const dir = directions[s];
            for (let j = 0; j < particlesPerSeed; j++) {
                if (particleCount >= numParticles) break;
                const t = j / (particlesPerSeed - 1);
                const distAlong = startDist + t * seedLength;
                let px = dir.x * distAlong;
                let py = dir.y * distAlong;
                let pz = dir.z * distAlong;
                // Thickness noise
                px += (Math.random() - 0.5) * seedRadius * 2;
                py += (Math.random() - 0.5) * seedRadius * 2;
                pz += (Math.random() - 0.5) * seedRadius * 2;
                positions[particleCount * 3] = px;
                positions[particleCount * 3 + 1] = py;
                positions[particleCount * 3 + 2] = pz;
                colors[particleCount * 3] = 1;
                colors[particleCount * 3 + 1] = 1;
                colors[particleCount * 3 + 2] = 1;
                particleCount++;
            }
        }

        const originalPositions = positions.slice();
        const phases = new Float32Array(particleCount);
        const velocities = new Float32Array(particleCount * 3);

        for (let i = 0; i < particleCount; i++) {
            phases[i] = Math.random() * Math.PI * 2;
        }

        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
        geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));

        const material = new THREE.PointsMaterial({
            size: 0.0035,
            sizeAttenuation: true,
            vertexColors: true,
        });

        const points = new THREE.Points(geometry, material);
        scene.add(points);
        camera.position.set(0, 0, 2.2);

        // State
        const currentEffect = "vortex";
        let intersectionPoint = null;
        let rotationX = 0;
        let rotationY = 0;
        let isDragging = false;
        let previousMouseX = 0;
        let previousMouseY = 0;

        // Mouse and touch events
        canvas.addEventListener("mousemove", (event) => {
            const rect = canvas.getBoundingClientRect();
            mouse.x = ((event.clientX - rect.left) / canvas.clientWidth) * 2 - 1;
            mouse.y = -((event.clientY - rect.top) / canvas.clientHeight) * 2 + 1;
            raycaster.setFromCamera(mouse, camera);
            const intersect = new THREE.Vector3();
            if (raycaster.ray.intersectPlane(plane, intersect)) {
                intersectionPoint = intersect;
            }
        });

        canvas.addEventListener("mouseleave", () => {
            intersectionPoint = null;
        });

        canvas.addEventListener("mousedown", (event) => {
            isDragging = true;
            previousMouseX = event.clientX;
            previousMouseY = event.clientY;
        });

        canvas.addEventListener("mousemove", (event) => {
            if (!isDragging) return;
            const deltaX = event.clientX - previousMouseX;
            const deltaY = event.clientY - previousMouseY;
            rotationY -= deltaX * 0.005;
            rotationX -= deltaY * 0.005;
            previousMouseX = event.clientX;
            previousMouseY = event.clientY;
        });

        canvas.addEventListener("mouseup", () => {
            isDragging = false;
        });

        canvas.addEventListener("touchstart", (event) => {
            isDragging = true;
            previousMouseX = event.touches[0].clientX;
            previousMouseY = event.touches[0].clientY;
        });

        canvas.addEventListener("touchmove", (event) => {
            if (!isDragging) return;
            const deltaX = event.touches[0].clientX - previousMouseX;
            const deltaY = event.touches[0].clientY - previousMouseY;
            rotationY -= deltaX * 0.005;
            rotationX -= deltaY * 0.005;
            previousMouseX = event.touches[0].clientX;
            previousMouseY = event.touches[0].clientY;
        });

        canvas.addEventListener("touchend", () => {
            isDragging = false;
        });

        // Animation loop
        const animate = (timestamp) => {
            const time = timestamp * 0.001;
            const positionAttribute = geometry.getAttribute("position");
            const colorAttribute = geometry.getAttribute("color");

            const radiusSwirl = 0.015;
            const angularSpeed = 0.8;
            const effectRadius = 0.3;
            let repelStrength = 0;

            if (currentEffect === "vortex") {
                repelStrength = 0.15;
            }

            const attractStrength = 0.05;
            const damping = 0.95;

            // Update rotations
            points.rotation.y += (rotationY - points.rotation.y) * 0.1;
            points.rotation.x += (rotationX - points.rotation.x) * 0.1;

            // Compute inverse quaternion for local mouse
            const euler = new THREE.Euler(points.rotation.x, points.rotation.y, points.rotation.z, "XYZ");
            const inverseQuaternion = new THREE.Quaternion().setFromEuler(euler).invert();

            let localIntersection = null;
            if (intersectionPoint) {
                localIntersection = intersectionPoint.clone().applyQuaternion(inverseQuaternion);
            }

            // Update particles
            for (let i = 0; i < particleCount; i++) {
                const idx = i * 3;
                const ox = originalPositions[idx];
                const oy = originalPositions[idx + 1];
                const oz = originalPositions[idx + 2];

                const theta = angularSpeed * time + phases[i];
                const swirlDx = radiusSwirl * Math.cos(theta);
                const swirlDy = radiusSwirl * Math.sin(theta);
                const targetX = ox + swirlDx;
                const targetY = oy + swirlDy;
                const targetZ = oz;

                let px = positionAttribute.getX(i);
                let py = positionAttribute.getY(i);
                let pz = positionAttribute.getZ(i);

                let vx = velocities[idx];
                let vy = velocities[idx + 1];
                let vz = velocities[idx + 2];

                // Mouse vortex effect
                if (localIntersection) {
                    const dx = px - localIntersection.x;
                    const dy = py - localIntersection.y;
                    const dz = pz - localIntersection.z;
                    const distSq = dx * dx + dy * dy + dz * dz;
                    const dist = Math.sqrt(distSq);

                    if (currentEffect === "vortex") {
                        if (distSq < effectRadius * effectRadius && dist > 0.05) {
                            const vortexStrength = 0.15;
                            const spiralForce = vortexStrength * (1 - dist / effectRadius);
                            const tangentX = -dy;
                            const tangentY = dx;
                            const tangentLength = Math.sqrt(tangentX * tangentX + tangentY * tangentY);
                            if (tangentLength > 0.001) {
                                vx += (tangentX / tangentLength) * spiralForce;
                                vy += (tangentY / tangentLength) * spiralForce;
                            }
                            const pullStrength = spiralForce * 0.3;
                            vx -= (dx / dist) * pullStrength;
                            vy -= (dy / dist) * pullStrength;
                        }
                    }
                }

                // Attract to target
                const attractDx = targetX - px;
                const attractDy = targetY - py;
                const attractDz = targetZ - pz;
                vx += attractDx * attractStrength;
                vy += attractDy * attractStrength;
                vz += attractDz * attractStrength;

                // Damping
                vx *= damping;
                vy *= damping;
                vz *= damping;

                // Update position
                px += vx;
                py += vy;
                pz += vz;

                positionAttribute.setXYZ(i, px, py, pz);
                velocities[idx] = vx;
                velocities[idx + 1] = vy;
                velocities[idx + 2] = vz;

                // Colors: bright white base, effect highlights
                let r = 4, g = 4, b = 4;

                if (localIntersection) {
                    const dx = px - localIntersection.x;
                    const dy = py - localIntersection.y;
                    const dz = pz - localIntersection.z;
                    const distSq = dx * dx + dy * dy + dz * dz;
                    const dist = Math.sqrt(distSq);
                    if (distSq < effectRadius * effectRadius) {
                        const angle = Math.atan2(dy, dx) + time * 5;
                        const intensity = (1 - dist / effectRadius) * 2 + 1;
                        r = (Math.sin(angle) * 0.5 + 0.5) * intensity * 4;
                        g = (Math.sin(angle + (Math.PI * 2) / 3) * 0.5 + 0.5) * intensity * 4;
                        b = (Math.sin(angle + (Math.PI * 4) / 3) * 0.5 + 0.5) * intensity * 4;
                    }
                }

                colorAttribute.setXYZ(i, r, g, b);
            }

            positionAttribute.needsUpdate = true;
            colorAttribute.needsUpdate = true;
            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        };

        requestAnimationFrame(animate);
    </script>
</body>
